  package   org . movsim . utilities ;   import   java . util . Random ;   public final class MyRandom  {   private static Random  rand =  new Random  ( ) ;   private MyRandom  ( )  {  throw  new IllegalStateException  ( "do not instanciate" ) ; }   public static void initializeWithSeed  (   long randomSeed )  {   rand =  new Random  ( randomSeed ) ; }   public static boolean isInitialized  ( )  {  return  rand != null ; }   public static  int nextInt  ( )  {  return  rand . nextInt  ( ) ; }   public static  int nextInt  (   int n )  {  return  rand . nextInt  ( n ) ; }   public static  double nextDouble  ( )  {  return  rand . nextDouble  ( ) ; }   public static  double getUniformDistribution  ( )  {  return   2 *  MyRandom . nextDouble  ( ) - 1 ; }   public static  double getUniformlyDistributedRandomizedFactor  (   double randomizationStrength )  {  return  1 +  randomizationStrength *  getUniformDistribution  ( ) ; }   public static  double getGaussiansDistributedRandomizedFactor  (   double sigma ,   double nSigmaCutoff )  {  return  1 +  Math . max  (   - nSigmaCutoff * sigma ,  Math . min  ( nSigmaCutoff ,  sigma *  rand . nextGaussian  ( ) ) ) ; } }